changeSet.sql:
CREATE OR REPLACE FUNCTION rename_issue_labeled_binding(bindings jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $rename_binding$ SELECT COALESCE(( SELECT jsonb_agg( CASE WHEN binding ? 'signals' THEN jsonb_set(binding, '{signals}', COALESCE(( SELECT jsonb_agg(DISTINCT renamed ORDER BY renamed) FROM jsonb_array_elements_text(binding->'signals') AS stored(signal), LATERAL (SELECT CASE stored.signal WHEN 'scm.issue.labeled' THEN 'scm.issue.updated' ELSE stored.signal END) AS mapped(renamed) ), '[]'::jsonb)) ELSE binding END ORDER BY position) FROM jsonb_array_elements(bindings) WITH ORDINALITY AS listed(binding, position) ), bindings) $rename_binding$;
UPDATE practice SET bindings = rename_issue_labeled_binding(bindings) WHERE bindings::text LIKE '%scm.issue.labeled%';
UPDATE curated_practice_override SET bindings = rename_issue_labeled_binding(bindings) WHERE bindings::text LIKE '%scm.issue.labeled%';
ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update; UPDATE practice_revision SET bindings = rename_issue_labeled_binding(bindings), review_rule_fingerprint = NULL WHERE bindings::text LIKE '%scm.issue.labeled%'; ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;
DROP FUNCTION rename_issue_labeled_binding(jsonb);

rollback.sql:
-- The narrower occasion is the only one the previous release can raise, so a binding -- goes back to it. A workspace that bound the wider occasion by hand after the upgrade -- lands on the labelled one, which is the closest thing that release has. CREATE OR REPLACE FUNCTION restore_issue_labeled_binding(bindings jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $restore_binding$ SELECT COALESCE(( SELECT jsonb_agg( CASE WHEN binding ? 'signals' THEN jsonb_set(binding, '{signals}', COALESCE(( SELECT jsonb_agg(DISTINCT restored ORDER BY restored) FROM jsonb_array_elements_text(binding->'signals') AS stored(signal), LATERAL (SELECT CASE stored.signal WHEN 'scm.issue.updated' THEN 'scm.issue.labeled' ELSE stored.signal END) AS mapped(restored) ), '[]'::jsonb)) ELSE binding END ORDER BY position) FROM jsonb_array_elements(bindings) WITH ORDINALITY AS listed(binding, position) ), bindings) $restore_binding$;
UPDATE practice SET bindings = restore_issue_labeled_binding(bindings) WHERE bindings::text LIKE '%scm.issue.updated%';
UPDATE curated_practice_override SET bindings = restore_issue_labeled_binding(bindings) WHERE bindings::text LIKE '%scm.issue.updated%';
ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update; UPDATE practice_revision SET bindings = restore_issue_labeled_binding(bindings), review_rule_fingerprint = NULL WHERE bindings::text LIKE '%scm.issue.updated%'; ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;
DROP FUNCTION restore_issue_labeled_binding(jsonb);
